$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

Write-Host ""
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host " SaborFlow - Etapa 13.5" -ForegroundColor Cyan
Write-Host " Senhas + bloqueio progressivo persistente" -ForegroundColor Cyan
Write-Host "=============================================" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path ".\package.json")) {
    throw "Execute este instalador na pasta raiz do projeto SaborFlow."
}

if (-not (Test-Path ".\database\migrations\030_admin_passkeys.sql")) {
    throw "Migration 030 nao encontrada. A Etapa 13.4 precisa estar presente antes da 13.5."
}

if (-not (Select-String -Path ".\lib\admin-user-db.ts" -Pattern "MIN_ADMIN_PASSWORD_LENGTH = 8" -SimpleMatch -Quiet)) {
    throw "lib\admin-user-db.ts esta em uma versao diferente da esperada. Nada foi alterado."
}

if (-not (Select-String -Path ".\app\api\auth\login\route.ts" -Pattern "const ACCOUNT_LIMIT = 8" -SimpleMatch -Quiet)) {
    throw "A rota de login esta em uma versao diferente da esperada. Nada foi alterado."
}

if (-not (Select-String -Path ".\components\admin\security-panel.tsx" -Pattern "A nova senha precisa ter pelo menos 12 caracteres." -SimpleMatch -Quiet)) {
    throw "security-panel.tsx esta em uma versao diferente da esperada. Nada foi alterado."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Etapa13-5-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$targets = @(
    "lib\admin-user-db.ts"
    "lib\security\login-lockout.ts"
    "app\api\auth\login\route.ts"
    "app\api\admin\password\change\route.ts"
    "components\admin\security-panel.tsx"
    "database\migrations\031_admin_password_lockout.sql"
)

Write-Host "Criando backup em:" -ForegroundColor Yellow
Write-Host $backupRoot
Write-Host ""

foreach ($target in $targets) {
    if (Test-Path $target) {
        $dest = Join-Path $backupRoot $target
        $destDir = Split-Path -Parent $dest
        if ($destDir) {
            New-Item -ItemType Directory -Force -Path $destDir | Out-Null
        }
        Copy-Item -LiteralPath $target -Destination $dest -Force
    }
}

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Write-Utf8Base64File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Base64
    )

    $directory = Split-Path -Parent $Path
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [System.Convert]::FromBase64String($Base64)
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    $fullPath = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) $Path))
    [System.IO.File]::WriteAllText($fullPath, $content, $utf8NoBom)
    Write-Host "Gravado: $Path" -ForegroundColor Green
}

Write-Host "Aplicando arquivos da Etapa 13.5..." -ForegroundColor Cyan
Write-Host ""

Write-Utf8Base64File -Path "lib\admin-user-db.ts" -Base64 ""
Write-Utf8Base64File -Path "lib\security\login-lockout.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\auth\login\route.ts" -Base64 ""
Write-Utf8Base64File -Path "app\api\admin\password\change\route.ts" -Base64 ""
Write-Utf8Base64File -Path "components\admin\security-panel.tsx" -Base64 ""
Write-Utf8Base64File -Path "database\migrations\031_admin_password_lockout.sql" -Base64 ""

Write-Host ""
Write-Host "Verificando whitespace do Git..." -ForegroundColor Cyan
git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou um problema. Use o backup em $backupRoot se precisar restaurar."
}

Write-Host ""
Write-Host "Etapa 13.5 aplicada LOCALMENTE." -ForegroundColor Green
Write-Host ""
Write-Host "Incluido:" -ForegroundColor Cyan
Write-Host " - senha administrativa: minimo 12 e maximo 128 caracteres"
Write-Host " - mantida exigencia de letra maiuscula e caractere especial"
Write-Host " - bloqueio progressivo persistente no PostgreSQL"
Write-Host " - 5 erros: 30s | 6: 1min | 7: 5min | 8: 15min | 9: 30min | 10+: 1h"
Write-Host " - contador decai apos 24h sem novas falhas"
Write-Host " - CPF e e-mail da mesma conta compartilham o mesmo bloqueio"
Write-Host " - identificadores inexistentes tambem recebem protecao sem revelar se a conta existe"
Write-Host " - troca/redefinicao de senha limpam bloqueios persistentes da conta"
Write-Host " - troca de senha limpa tambem a sessao Superadmin"
Write-Host " - last_login_at passa a representar conclusao do MFA/Passkey, nao apenas senha correta"
Write-Host ""
Write-Host "IMPORTANTE:" -ForegroundColor Yellow
Write-Host " - a Migration 031 foi apenas CRIADA"
Write-Host " - ela NAO foi executada no banco"
Write-Host " - nenhum commit foi feito"
Write-Host " - nenhum deploy foi feito"
Write-Host ""
Write-Host "Status atual:" -ForegroundColor Cyan
git status --short
Write-Host ""
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
Write-Host ""
